abstract class ConflictResolver<TLocal, TRemote, TCompanion> {
  /// Resolves conflict between local and remote data.
  /// Returns the companion to persist locally.
  TCompanion resolve(TLocal local, TRemote remote);

  /// Creates a companion from remote data when no local data exists.
  TCompanion fromRemote(TRemote remote);
}

Future<void> _syncPendingTransfers({int? specificId}) async {
  final db = Get.find<LocalStorage>().db;
  var query = db.select(db.pendingTransfers)
    ..where((t) => t.status.equals('pending'));
  if (specificId != null) {
    query.where((t) => t.id.equals(specificId));
  }
  final pending = await query.get();
  if (pending.isEmpty) return;
  final api = Get.find<TransferApiDatasource>();

  for (final item in pending) {
    try {
      final response = await api.submitTransfer(
        TransferRequest(
          fromAccountId: item.fromAccountId,
          toContactId: item.toContactId,
          amount: item.amount,
          note: item.note ?? '',
        ),
      );
      await (db.update(db.pendingTransfers)..where((t) => t.id.equals(item.id)))
          .write(const PendingTransfersCompanion(status: Value('synced')));
    } on ErrorData catch (e) {
      final accLocal = Get.find<AccountLocalDatasource>();
      final acc = await accLocal.getAccount(item.fromAccountId);
      if (acc != null) {
        await accLocal.updateBalance(acc.serverId, acc.balance + item.amount);
      }
      await (db.update(db.pendingTransfers)..where((t) => t.id.equals(item.id)))
          .write(PendingTransfersCompanion(status: const Value('failed'), errorMessage: Value<String?>(e.message)));
    }
  }
}

class AccountRepository {
  final AccountLocalDatasource _local;

  AccountRepository(this._local);

  Future<List<Account>> getAccounts() => _local.getAccounts();
  Stream<List<Account>> watchAccounts() => _local.watchAccounts();
  Future<Account?> getAccount(String serverId) => _local.getAccount(serverId);
  Future<void> updateBalance(String serverId, double newBalance) =>
      _local.updateBalance(serverId, newBalance);
}

class AuthBinding extends Bindings {
  @override
  void dependencies() {
    Get.lazyPut<AuthLocalDatasource>(() => AuthLocalDatasource(Get.find()));
    Get.lazyPut<AuthController>(() => AuthController());
  }
}

class AuthController extends GetxController {
  final AuthLocalDatasource _authStorage = Get.find<AuthLocalDatasource>();
  final LocalAuthentication _auth = LocalAuthentication();

  final pin = ''.obs;
  final confirmPin = ''.obs;
  final pinError = RxnString();
  final isCreating = false.obs;
  final isConfirmStep = false.obs;
  static const int pinLength = 6;

  Future<bool> authenticateWithBiometrics() async {
    try {
      return await _auth.authenticate(
        localizedReason: 'Verify your identity to access Mini Bank',
        biometricOnly: true,
        persistAcrossBackgrounding: true,
      );
    } catch (_) {
      return false;
    }
  }

  Future<void> _verifyPin() async {
    final valid = await _authStorage.verifyPin(pin.value);
    if (valid) {
      await onAuthSuccess();
    } else {
      pin.value = '';
      pinError.value = 'Wrong PIN';
    }
  }
}

class ApiClient {
  late final Dio _dio;

  ApiClient() {
    _dio = Dio(
      BaseOptions(
        baseUrl: AppConfig.baseUrl,
        connectTimeout: AppConfig.connectTimeout,
        receiveTimeout: AppConfig.receiveTimeout,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
      ),
    );

    _dio.interceptors.addAll([
      LogInterceptor(request: true, requestBody: true, responseBody: true, error: true),
      InterceptorsWrapper(
        onError: (error, handler) {
          handler.next(error);
        },
      ),
    ]);
  }
}

class ErrorData {
  ErrorData({this.code, this.message});

  ErrorData.fromJson(dynamic json) {
    code = json['code'];
    message = json['message'];
  }
  num? code;
  String? message;

  @override
  String toString() => 'ErrorData(code: $code, message: $message)';
}
